// Generate a single transactional SQL Editor installer from the reviewed migrations.
import { readdir, readFile, writeFile } from 'node:fs/promises';
const root = new URL('../', import.meta.url);
const directory = new URL('supabase/migrations/',root);
const files = (await readdir(directory)).filter(name => name.endsWith('.sql')).sort();
if (!files.length) throw new Error('No migrations found.');
let sql = `-- SwapFix: first installation in a project with no SwapFix tables.
-- Generated by node scripts/build-database-install.mjs. Do not edit this file.
-- Run the entire file in the selected Supabase project's SQL Editor.
-- Existing unrelated tables are preserved. Any error rolls back this installation.
-- Do not run this after the migrations have already been installed with the CLI.
begin;
do $$ begin
  if to_regclass('public.profiles') is not null or to_regnamespace('swapfix_private') is not null then
    raise exception 'SwapFix or a conflicting profiles table already exists. Review migration history instead of reinstalling.';
  end if;
end $$;
do $$ begin
  if exists (select 1 from storage.buckets where id in ('listing-images', 'avatars', 'repair-images', 'offer-images')) then
    raise exception 'A SwapFix-named Storage bucket already exists. Review it before installing.';
  end if;
end $$;
\n`;
for (const name of files) sql += `\n-- SOURCE: ${name}\n${await readFile(new URL(name,directory),'utf8')}\n`;
const tables = [...sql.matchAll(/create table public\.([a-z_]+)\s*\(/g)].map(match => `'${match[1]}'`);
sql += `\nnotify pgrst, 'reload schema';\ncommit;\n\n-- Verification: the ${tables.length} SwapFix tables and their RLS status.\nselect tablename, rowsecurity from pg_tables\nwhere schemaname = 'public' and tablename in (${tables.join(', ')})\norder by tablename;\n`;
await writeFile(new URL('supabase/install.sql',root),sql,'utf8');
console.log(`Built supabase/install.sql from ${files.length} migrations (${Buffer.byteLength(sql)} bytes).`);
